import { spawn } from 'node:child_process';
const bin = '/harness-state/.bun/bin/gbrain';
const p = spawn(bin, ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, GBRAIN_HOME: '/harness-state', PATH: '/harness-state/.bun/bin:' + process.env.PATH },
  stdio: ['pipe', 'pipe', 'pipe'], cwd: '/tmp',
});
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', d => process.stderr.write('[serve] ' + d));
const rpc = (method, params) => new Promise((res, rej) => { const myId = ++id; waiters.set(myId, res); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: myId, method, params }) + '\n'); setTimeout(() => rej(new Error('timeout ' + method)), 60000); });
const call = async (name, args) => { const r = await rpc('tools/call', { name, arguments: args }); const t = r.result?.content?.map(c => c.text).join('\n') ?? JSON.stringify(r.error); return { isError: r.result?.isError, text: t }; };
const show = (label, o) => console.log(`\n=== ${label} ===\n` + (typeof o === 'string' ? o : JSON.stringify(o, null, 1)).slice(0, 1500));
try {
  const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'openclaw-install-check', version: '1' } });
  show('initialize', init.result?.serverInfo);
  p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
  const tl = await rpc('tools/list', {});
  show('tools/list', tl.result.tools.map(t => t.name).join(', '));
  const mode = process.argv[2] || 'all';
  if (mode === 'all' || mode === 'write') {
    show('remember', await call('remember', { fact: 'GBrain MCP install-check: marker quartz-heron-4482 written over MCP from OpenClaw', provenance: 'install-check' }));
  }
  show('recall', await call('recall', { query: 'quartz-heron-4482' }));
  show('recall (earlier CLI marker)', await call('recall', { query: 'zephyr-orchid-7731' }));
} catch (e) { console.error('ERR', e); process.exitCode = 1; }
p.kill();

